variables.body:
// Main
if (!row) {
    $ctrl.selectedEntity = null;
    $ctrl.selectedEntityName = null;
    $ctrl.selectedEntityDetails = "";

    if (document.getElementById("details")) document.getElementById("details").innerHTML = null;
    return;
}

const isEditing = $ctrl.isEditingPayslip;
if ($ctrl.selectedEntity && row.Id !== $ctrl.selectedEntity.Id) {
    const discardChanges = await $ctrl.utils.handleUnsavedChanges(isEditing);
    const currentRowIndex = $ctrl.filteredTableData.findIndex(row => row.Id === $ctrl.selectedEntity.Id);

    if (isEditing && !discardChanges) {
        $ctrl.utils.setSelectedBelliniTableRow(currentRowIndex);
        return;
    }
}

$ctrl.selectedEntity = row;
$ctrl.selectedEntityDetails = "";

populateEntityDetails(row);
injectDetailsIntoElement();
setEntityName(row);
$ctrl.setInputValues();

function resetSelectedEntity() {
    $ctrl.selectedEntity = null;
    $ctrl.selectedEntityName = null;
    $ctrl.selectedEntityDetails = "";
}

function clearDetailsElement() {
    const detailsElement = document.getElementById("details");
    if (detailsElement) detailsElement.innerHTML = "";
}

// Helper Functions
function setEntityName(row) {
    $ctrl.selectedEntityName = row.PayPeriodDisplayName;
}

function populateEntityDetails(row) {
    for (const [key, value] of Object.entries(row)) {
        if (key.startsWith("$$") || (isExcludedKey(key, value) && key !== "PayPeriodRate")) continue;
        switch (key) {
            case "PayPeriodRate":
                appendPayPeriodRate(row.Frequency, value);
                break;
            case "WorkerName":
                appendWorkerName(value);
                break;
            case "BankInfo":
                Object.entries(value).forEach(([key, value]) => key !== "Id" ? appendGeneralDetails(key, value) : undefined);
                break;
            case "CreatedDate":
                return; // Stop processing at CreatedDate
            case "AccrualBalance":
                if (value.length > 0) {
                    $ctrl.selectedEntityDetails += appendSectionTitle("Leave Credits");
                    appendAccrualBalances(value);
                }
                break;
            case "GrossPay":
            case "TotalDeductions":
            case "NetPay":
                appendTotals(key, value);
                break;
            default:
                if (isStatutoryCompliance(key)) {
                    appendStatutoryCompliance(value);
                } else if (isPayComponent(key)) {
                    appendPayComponents(key, value, row);
                } else {
                    appendGeneralDetails(key, value);
                }
        }
    }
}

function injectDetailsIntoElement() {
    const element = document.getElementById("details");
    if (element) {
        element.innerHTML = $ctrl.selectedEntityDetails;
    } else {
        $ctrl.$timeout(injectDetailsIntoElement, 100);
    }
}

// Utility Functions
function isExcludedKey(key, value) {
    const excludedKeys = [
        "Id", "PayPeriod", "Payroll", "Department", "Position",
        "Frequency", "GrossTaxable", "GrossNonTaxable", "PreTaxDeductions", "NetTaxable", "Taxes",
        "PostTaxDeductions", "Ytd"
    ];
    return excludedKeys.some(item => key.includes(item)) || value === undefined;
}

function appendPayPeriodRate(frequency, value) {
    const formattedFrequency = formatFrequency(frequency);
    const formattedValue = formatCurrency(value);
    $ctrl.selectedEntityDetails += `
        <div style="display: flex; width: 100%;">
            <div>${formattedFrequency} Rate</div>
            <div style="flex-grow: 1;"></div>
            <div>${formattedValue}</div>
        </div>
        <br>`;
}

function appendWorkerName(name) {
    $ctrl.selectedEntityDetails += `<div>${name}</div>`;
}

function appendStatutoryCompliance(complianceList) {
  complianceList.forEach(({ Name, Number }) => {
    const uniqueId = `item-${Name.replace(/\s+/g, '-')}-${Math.random().toString(36).substring(2, 15)}`;

    $ctrl.selectedEntityDetails += `
      <div style="display: flex; width: 100%; align-items: center;"> 
        <div style="min-width: 150px;">${Name}</div>
        <div style="flex-grow: 1;"></div>
        <div style="display: flex; align-items: center;">
          <div id="${uniqueId}-value" style="margin-right: 5px;">
            ${"*".repeat(Number.length)}
          </div>
          <button type="button" id="${uniqueId}-button" style="border: none; padding: 0; background-color: transparent; cursor: pointer;">
            <i class="fas fa-eye"></i>
          </button>
        </div>
      </div>`;

    $ctrl.$timeout(() => {
      const button = document.getElementById(`${uniqueId}-button`);
      const valueElement = document.getElementById(`${uniqueId}-value`);

      if (button && valueElement) {
        button.addEventListener('click', () => {
          if (!$ctrl.hasBeenUnmasked) {
            $ctrl.handleSensitiveInfoMasking();
            $ctrl.hasBeenUnmasked = true;
          }
          const isMasked = valueElement.textContent.startsWith("*");
          valueElement.textContent = isMasked? Number: "*".repeat(Number.length);
          button.innerHTML = isMasked? '<i class="fas fa-eye-slash"></i>': '<i class="fas fa-eye"></i>';
        });
      }
    }, 500);
  });
}

function appendSectionTitle(key) {
    const title = key.toUpperCase().replace("LOGS", "S");
    return `
        <br>
        <div style="width: 100%; font-weight: bold; border: 1px solid black; padding: 0.5rem; text-align: center; box-sizing: border-box;">
            ${title}
        </div>
        <br>`;
}

function appendPayComponents(key, components, row) {
    $ctrl.selectedEntityDetails += appendSectionTitle(key);

    if (key === "DeductionLogs") {
        appendPayComponentCategory("Pre-tax", components.filter(c => c.Type === "PRETAX"), row.PreTaxDeductions);
        tempAppendNetTaxable("Net Taxable", [{ Name: "Gross Taxable", EmployeeAmount: row.GrossTaxable }, { Name: "Pre-tax Deductions", EmployeeAmount: -Math.abs(row.PreTaxDeductions) }], row.NetTaxable);
        appendPayComponentCategory("Tax", components.filter(c => c.ComponentClass === "TAX"), row.Taxes);
        appendPayComponentCategory("Post-tax", components.filter(c => c.Type === "POSTTAX"), row.PostTaxDeductions);
    } else {
        const categorizedComponents = categorizePayComponents(components);
        appendPayComponentCategory("Non-taxable", categorizedComponents.nonTaxable, row.GrossNonTaxable);
        appendPayComponentCategory("Taxable", categorizedComponents.taxable, row.GrossTaxable);
    }
}

function appendPayComponentCategory(category, components, total = null) {
    const validComponents = components.filter(component => typeof component.EmployeeAmount === "number");
    if (!validComponents.length) return;

    const colWidth = "120px";

    $ctrl.selectedEntityDetails += `<div style="background-color: #F2F2F2;">`;
    $ctrl.selectedEntityDetails += `<hr style="border: none; height: 0; border-bottom: 0.5px solid black;">`;

    $ctrl.selectedEntityDetails += `
        <div style="display: flex; width: 100%; padding: 0 1rem; box-sizing: border-box;">
            <div style="flex-grow: 1; font-weight: bold;">${category}</div>
            <div style="width: ${colWidth}; text-align: right; font-size: 0.85em; color: #555; align-self: flex-end;">YTD</div>
            <div style="width: ${colWidth}; text-align: right; font-size: 0.85em; color: #555; align-self: flex-end;">CURRENT</div>
        </div>
        <hr style="border: none; height: 0; border-bottom: 0.5px dashed black;">
        <br>`;

    $ctrl.selectedEntityDetails += `<div style="padding: 0 1rem;">`;
    validComponents.forEach(({ Name, EmployeeAmount, Ytd }) => {
        const formattedAmount = formatCurrency(EmployeeAmount);

        const ytdAmount = formatCurrency(Ytd?.EmployeeAmount || 0);

        $ctrl.selectedEntityDetails += `
            <div style="display: flex; width: 100%; margin-bottom: 0.25rem;">
                <div style="flex-grow: 1;">${Name}</div>
                <div style="width: ${colWidth}; text-align: right;">${ytdAmount}</div>
                <div style="width: ${colWidth}; text-align: right;">${formattedAmount}</div>
            </div>`;
    });
    $ctrl.selectedEntityDetails += `</div>`;

    if (total !== null) {
        const totalLabel = category === "Taxable" || category === "Non-taxable"
            ? "Gross " + category
            : category + " Deductions";

        const ytdKeyMap = {
            "Pre-tax": "PreTaxDeductions",
            "Tax": "Taxes",
            "Post-tax": "PostTaxDeductions",
            "Non-taxable": "GrossNonTaxable",
            "Taxable": "GrossTaxable"
        };

        const ytdKey = ytdKeyMap[category];
        const ytdValue = row?.Ytd?.[ytdKey] || 0;

        $ctrl.selectedEntityDetails += `
            <br>
            <hr style="border: none; height: 0; border-bottom: 0.5px dashed black;">
            <div style="display: flex; width: 100%; padding: 0 1rem; box-sizing: border-box;">
                <div style="flex-grow: 1; font-weight: bold;">${totalLabel}</div>
                <div style="width: ${colWidth}; text-align: right; font-weight: bold;">${formatCurrency(ytdValue)}</div>
                <div style="width: ${colWidth}; text-align: right; font-weight: bold;">${formatCurrency(total)}</div>
            </div>`;
    }

    $ctrl.selectedEntityDetails += `
        <hr style="border: none; height: 0; border-bottom: 0.5px solid black;">
        </div>
        <br>`;
}

function appendTotals(key, value) {
    const labelMap = {
        "GrossPay": "GROSS PAY",
        "TotalDeductions": "TOTAL DEDUCTIONS",
        "NetPay": "NET PAY"
    };
    const label = labelMap[key] || key;
    const fontStyle = key === "NetPay" ? "normal" : "italic";

    const colWidth = "120px";

    const ytdValue = row?.Ytd?.[key] || 0;
    const formattedYtd = formatCurrency(ytdValue);
    const formattedCurrent = formatCurrency(value);

    $ctrl.selectedEntityDetails += `
        <hr style="border: none; height: 0; border-top: 1px solid black; margin: 0;">
        <div style="display: flex; width: 100%; padding: 0.5rem 1rem; box-sizing: border-box;">
            <div style="flex-grow: 1; font-style: ${fontStyle}; font-weight: bold;">${label}</div>
            <div style="width: ${colWidth}; text-align: right; font-style: ${fontStyle}; font-weight: bold;">${formattedYtd}</div>
            <div style="width: ${colWidth}; text-align: right; font-style: ${fontStyle}; font-weight: bold;">${formattedCurrent}</div>
        </div>
        <hr style="border: none; height: 0; border-top: 1px solid black; margin: 0;">
        ${key === "NetPay" ? `` : `<br>`}`;
}
function appendAccrualBalances(balances) {
    $ctrl.selectedEntityDetails += `
        <div style="background-color: #F2F2F2; ">
        <hr style="border: none; height: 0; border-bottom: 0.5px solid black; ">
        <div style="padding: 1rem; ">`;

    balances.forEach(({ AccrualName, Balance }) => {
        const formattedBalance = formatCurrency(Balance, 3, false);
        $ctrl.selectedEntityDetails += `
            <div style="display: flex; width: 100%; ">
                <div>${AccrualName}</div>
                <div style="flex-grow: 1;"></div>
                <div>${formattedBalance}</div>
            </div>`;
    });

    $ctrl.selectedEntityDetails += `
    </div>
    <hr style="border: none; height: 0; border-bottom: 0.5px solid black; ">
    </div>`;
}

function appendGeneralDetails(key, value) {
    const uniqueId = `item-${key.replace(/\s+/g, '-')}-${Math.random().toString(36).substring(2, 15)}`;
    const isNumberKey = key.includes("Number");

    $ctrl.selectedEntityDetails += `
    <div style="display: flex; width: 100%; align-items: center;"> <div style="min-width: 150px;">${key}</div>
      <div style="flex-grow: 1;"></div>
      <div style="display: flex; align-items: center;">
        <div id="${uniqueId}-value" style="margin-right: 5px;">
            ${isNumberKey ? "*".repeat(value.length) : value}
        </div>
        ${isNumberKey ? `
            <button type="button" id="${uniqueId}-button" style="border: none; padding: 0; background-color: transparent; cursor: pointer">
            <i class="fas fa-eye"></i>
            </button>`
            : ''}
      </div>
    </div>`;

    $ctrl.$timeout(() => {
        const button = document.getElementById(`${uniqueId}-button`);
        const valueElement = document.getElementById(`${uniqueId}-value`);

        if (button && valueElement) {
            // Event listener for the button only
            button.addEventListener('click', () => {
                if (!$ctrl.hasBeenUnmasked) {
                    $ctrl.handleSensitiveInfoMasking();
                    $ctrl.hasBeenUnmasked = true; // Set the flag to prevent further calls
                }
                const isMasked = valueElement.textContent.startsWith("*");
                valueElement.textContent = isMasked ? value : "*".repeat(value.length);
                button.innerHTML = isMasked ? '<i class="fas fa-eye-slash"></i>' : '<i class="fas fa-eye"></i>'; // Toggle icon
            });
        }
    }, 500);
}

function formatCurrency(amount, fractionDigits = 2, isCurrency = true, currency = row.EarningLogs[0]?.Currency) {
    return `${isCurrency && currency && currency.CurrencySymbol ? `${currency.CurrencySymbol}` : ``} ${amount.toLocaleString("en-US", {
        minimumFractionDigits: (currency && currency.CurrencyPrecision) || fractionDigits,
        maximumFractionDigits: (currency && currency.CurrencyPrecision) || fractionDigits
    })}`;
}

function formatFrequency(frequency) {
    return frequency
        .toLowerCase()
        .split(/[-\s]/)
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(frequency.includes("-") ? "-" : " ");
}

function categorizePayComponents(components) {
    return {
        nonTaxable: components.filter(comp => !comp.IsTaxable),
        taxable: components.filter(comp => comp.IsTaxable)
    };
}

function isStatutoryCompliance(key) {
    return key.includes("StatutoryCompliance");
}

function isPayComponent(key) {
    const relevantKeywords = ["Earning", "Deduction"];
    return relevantKeywords.some(kw => key.includes(kw) && !key.includes("Tax") && !key.includes("Total"));
}

function tempAppendNetTaxable(category, components, total = null) {
    if (!components.filter(component => typeof component.EmployeeAmount === "number").length) return;

    $ctrl.selectedEntityDetails += `<div>`;
    $ctrl.selectedEntityDetails += `<hr style="border: none; height: 0; border-bottom: 0.5px solid black;">`;

    $ctrl.selectedEntityDetails += `<div style="padding: 1rem 0; ">`;
    components.filter(component => typeof component.EmployeeAmount === "number").forEach(({ Name, EmployeeAmount }) => {
        const formattedAmount = formatCurrency(EmployeeAmount);
        $ctrl.selectedEntityDetails += `
            <div style="display: flex; width: 100%;">
                <div>${Name}</div>
                <div style="flex-grow: 1;"></div>
                <div>${formattedAmount}</div>
            </div>`;
    });
    $ctrl.selectedEntityDetails += `</div>`;

    if (total !== null) {
        $ctrl.selectedEntityDetails += `
            <hr style="border: none; height: 0; border-bottom: 0.5px solid black;">
            <div style="display: flex; width: 100%;">
                <div style="font-style: italic;">${category.toUpperCase()}</div>
                <div style="flex-grow: 1;"></div>
                <div style="font-style: italic;">${formatCurrency(total)}</div>
            </div>`;
    }

    $ctrl.selectedEntityDetails += `
        <hr style="border: none; height: 0; border-bottom: 0.5px solid black;">
        </div>
        <br>`;
}

const date = new Date(dateString);

const pad = (num, size) => String(num).padStart(size, '0');

const year = date.getUTCFullYear();
const month = pad(date.getUTCMonth() + 1, 2);
const day = pad(date.getUTCDate(), 2);
const hours = pad(date.getUTCHours(), 2);
const minutes = pad(date.getUTCMinutes(), 2);
const seconds = pad(date.getUTCSeconds(), 2);
const milliseconds = pad(date.getUTCMilliseconds(), 3);

return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`;

switch (result) {
    case "OK":
        $ctrl.$notificationManager.show(message, {
            delay: 3500,
            icon: 'check',
            color: 'success',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case "INFO":
        $ctrl.$notificationManager.show(message, {
            delay: 2500,
            icon: 'info-circle',
            color: 'primary',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case "WARNING":
        $ctrl.$notificationManager.show(message, {
            delay: 2500,
            icon: 'exclamation-triangle',
            color: 'warning',
            dismissible: true,
            animation: 'fade'
        });
        break;

    default:
        $ctrl.$notificationManager.show(message, {
            delay: 5000,
            icon: 'exclamation-circle',
            color: 'danger',
            dismissible: true,
            animation: 'fade'
        });
        break;
}

const limit = 1000;
const offset = 0;

return $ctrl.payrollAppApi[endpoint](
    { limit: limit, offset: offset },
    { headers: $ctrl.authCookies.setHeaders() }
)
    .then((result) => result.data[entity])
    .catch((reason) => {
        $ctrl.utils.toast(reason.data.message, reason.data.result);
        throw reason;
    });

const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if ((/^(is|need|with|can|allow|active|salaried|enabled|final)/i.test(key) || key.toLowerCase() === "employercontribution") && method === "POST") {
            result[titleCaseKey] = form[key] || false;
        } else if (key.includes("Date") && form[key]) {
            result[titleCaseKey] = $ctrl.parseDate(form[key]);
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

if (method === "POST") $ctrl.isInserting = true;
if (method === "PUT") $ctrl.isUpdating = true;

$ctrl.payrollAppApi[endpoint](
    {},
    {
        ...$ctrl.buildRequestBody(form, method),
        ...(method === "PUT" ? { "Id": $ctrl.selectedEntity.Id } : {})
    },
    { headers: $ctrl.authCookies.setHeaders() }
).then(result => {
    $ctrl.utils.toast(`Successfully ${$ctrl.isInserting ? "added" : "edited"} ${entityName}`, result.data.result);
    if ($ctrl.isInserting) $ctrl.setIsAdding();
    if ($ctrl.isUpdating) $ctrl.setIsEditing();
    $ctrl.getAllEntities(true);
    $ctrl.utils.resetForm(form);
})
    .catch(reason => {
        $ctrl.toast(reason.data.message, reason.data.result);
    })
    .finally(() => {
        if ($ctrl.isInserting) $ctrl.isInserting = false;
        if ($ctrl.isUpdating) $ctrl.isUpdating = false;
    });

const toBeDeletedEntity = $ctrl.selectedEntityName;
let isConfirmed;
$ctrl.isDeleting = true;

await $ctrl.$modal.open("delete-entity-modal", {
    props:
    {
        EntityName: $ctrl.selectedEntityName,
        EntityDetails: $ctrl.selectedEntityDetails
    }
}).then(response => isConfirmed = response.result === "ok");

if (isConfirmed) {
        $ctrl.payrollAppApi[endpoint](
            { id: $ctrl.selectedEntity.Id },
            { headers: $ctrl.authCookies.setHeaders() }
        ).then(result => {
            $ctrl.getAllEntities();
            $ctrl.toast(`Successfully deleted ${toBeDeletedEntity}`, result.data.result);
            $ctrl.isDeleting = false;
        }).catch(reason => {
            $ctrl.toast(reason.data.message, reason.data.result);
            $ctrl.isDeleting = false;
        }).finally(() => {
            $ctrl.isDeleting = false;
        });

} else {
    $ctrl.isDeleting = false;
}

const isProd = $ctrl.$env.current.name === "prod";
const isDev = $ctrl.$env.current.name === "deev";

if ((isProd || isDev) && !$ctrl.$cookies.get("id_token")) {
    window.location.href = "#!/user_login";
    return;
}

if ((isProd || isDev) && $ctrl.$stateParams.id === ":id") {
    window.location.href = "#!/payroll_processing";
    return;
}

const usrIsAdmin = await $ctrl.authService.redirectWorker();
if(!usrIsAdmin) return;

if ($ctrl.isFirstLoad) $ctrl.authCookies.getAuthToken().then(() => $ctrl.isFirstLoad = false);

// Resets
$ctrl.currentPage = 1;
$ctrl.entityUiStateService.initializationError = null;

$ctrl.selectedEntity = null;
$ctrl.selectedEntityName = null;
$ctrl.selectedEntityDetails = null;

$ctrl.filterTarget = null;

// Main
$ctrl.isGettingEntities = true;

// Append Font Awesome link if not already present
if (!document.querySelector('link[href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css"]')) {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css';
    document.head.appendChild(link);
}

if (isCUD && $ctrl.isSensitiveInfoMasked && $ctrl.hasBeenUnmasked) {
    $ctrl.isSensitiveInfoMasked = true;
    $ctrl.hasBeenUnmasked = false;
}

Promise.all([
    $ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_GeneratePayrollReport({
        id: $ctrl.$stateParams.id,
        maskSensitiveWorkerInfo: $ctrl.isSensitiveInfoMasked
    }, { headers: $ctrl.authCookies.setHeaders() }).then(result => result.data),
    $ctrl.getData("lonti_app_payroll_service_company_SelectAllCompany", "company"),
    $ctrl.getData("lonti_app_payroll_service_employment_info_SelectAllEmploymentInfo", "employmentinfo"),
]).then(results => $ctrl.$timeout(() => {
    const [
        payrollReport,
        companies,
        employmentinfo
    ] = results;

    $ctrl.dataHandlers.setContext($ctrl);

    $ctrl.dataHandlers.processData(companies, {
        mapToLabelValue: 'companyMap',
        entityList: companies,
        mapLabelKey: 'LegalName',
        mapValueKey: 'Id'
    });

    $ctrl.dataHandlers.processData(employmentinfo, {
        ctrlDataName: "employmentInfo"
    });

    $ctrl.payrollReport = payrollReport;

    $ctrl.processPayrollReport();

    if (!$ctrl.globalSelectedCompany.companyMap.length > 0) $ctrl.globalSelectedCompany.companyMap = $ctrl.companyMap.map(obj => ({ ...obj }));


    const payPeriod = payrollReport.PayrollReport.PayrollRun.PayPeriod;
    const paySchedule = payPeriod.PaySchedule;
    const company = payPeriod.Company ?? paySchedule.Company;
    const companyId = company?.Id;
    const companyLegalName = company?.LegalName ?? $ctrl.globalSelectedCompany.companyMap.find(company => company.value === companyId)?.label;

    if (companyId && companyLegalName && companyId !== $ctrl.globalSelectedCompany.companyId) {
        $ctrl.utils.toast(`Switching Payroll Run's Company ${companyLegalName ? `(${companyLegalName})` : ""}`, "INFO");
        $ctrl.globalSelectedCompany.setCompany(companyId, companyLegalName);
    }

    $ctrl.globalSelectedCompany.setMenuItems();
    $ctrl.globalSelectedCompany.clearCompanyMenuItems();

    if ($ctrl.tempStoredEntityId) {
        $ctrl.setSelectedEntity($ctrl.paySlips.find(payslip => payslip.Id === $ctrl.tempStoredEntityId));
        $ctrl.tempStoredEntityId = null;
    }

    $ctrl.isGettingEntities = false;
}, 500)).catch(error => {
    $ctrl.entityUiStateService.initializationError = error.data?.message || "Failed to load required data.";
    $ctrl.utils.toast($ctrl.entityUiStateService.initializationError, "ERROR");
    console.error("Data loading failed:", error);

    if (isProd || isDev) {
        $ctrl.$state.go("payroll_processing");
    }

}).finally(() => $ctrl.isGettingEntities = false);

const payrollReportObj = $ctrl.payrollReport.PayrollReport.PayrollRun;
const payrollReport = Object.entries(payrollReportObj);

const payPeriodObj = payrollReportObj.PayPeriod;
const payScheduleObj = payPeriodObj.PaySchedule;

$ctrl.rightColumn = payrollReport.filter(row =>
    !["Id", "DisplayName", "PostingDate", "ProcessDate", "PayPeriod", "Status", "RunType", "TotalEmployees", "Description", "OffCycleReason"].includes(row[0])
);

let ctr = 0;
$ctrl.rightColumn.forEach(([key, value]) => {
    if (key.includes("Total")) $ctrl.rightColumn[ctr][1] = value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    ctr++;
})

$ctrl.rightColumn.unshift(["Section", "Calculations"]);

$ctrl.leftColumn = [
