const fileName = $ctrl.selectedEntity.WorkerName + " - " + $ctrl.parseDate($ctrl.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[1] + " " + $ctrl.parseDate($ctrl.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[2] + "-" + $ctrl.parseDate($ctrl.selectedEntity.PayPeriodEndDate).split(" ")[0].split("-")[2] + " " + $ctrl.parseDate($ctrl.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[0];

// Bond paper dimensions in points (72 points per inch)
const BOND_PAPER_WIDTH = 8.5 * 72; // 612 points
const BOND_PAPER_HEIGHT = 11 * 72; // 792 points

// Get the div element
const divElement = document.getElementById(divId);
if (!divElement) {
    console.error(`Div with ID '${divId}' not found`);
    return;
}

// Save the original styles to restore later
const originalStyle = {
    width: divElement.style.width,
    margin: divElement.style.margin,
};

try {
    // Temporarily set the div to full width
    divElement.style.width = '100%';
    divElement.style.margin = '0 auto'; // Center the content horizontally if needed

    // Use html2canvas to capture the div as a canvas
    const canvas = await html2canvas(divElement, { scale: 2 }); // Higher scale for better resolution

    // Get the canvas dimensions
    const canvasWidth = canvas.width;
    const canvasHeight = canvas.height;

    // Calculate scale to fit the bond paper dimensions
    const scale = Math.min(BOND_PAPER_WIDTH / canvasWidth, BOND_PAPER_HEIGHT / canvasHeight);

    const imgWidth = canvasWidth * scale;
    const imgHeight = canvasHeight * scale;

    // Convert the canvas to an image
    const imgData = canvas.toDataURL('image/png');

    // Initialize jsPDF with bond paper size
    const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'pt',
        format: [BOND_PAPER_WIDTH, BOND_PAPER_HEIGHT],
    });

    // Center the image on the bond paper
    const xOffset = (BOND_PAPER_WIDTH - imgWidth) / 2;
    const yOffset = (BOND_PAPER_HEIGHT - imgHeight) / 2;

    // Add the image to the PDF
    pdf.addImage(imgData, 'PNG', xOffset, yOffset, imgWidth, imgHeight);

    // Save the PDF
    pdf.save(fileName || 'document.pdf');
} catch (error) {
    console.error('Error generating PDF:', error);
} finally {
    // Restore the original styles
    divElement.style.width = originalStyle.width;
    divElement.style.margin = originalStyle.margin;
}

